import Foundation

/// Pasteboard types that password managers and other apps set to say
/// "do not record this". See http://nspasteboard.org.
public enum ClipboardPrivacy {
    public static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    public static func shouldRecord(types: [String]) -> Bool {
        !types.contains(where: ignoredTypes.contains)
    }
}

/// Most-recent-first list of copied text. Lives in memory only.
public struct ClipboardHistory: Sendable, Equatable {
    public struct Entry: Identifiable, Hashable, Sendable {
        public enum Kind: Sendable { case link, text, code }

        public let id: UUID
        public let text: String
        public let copiedAt: Date
        public var isPinned: Bool

        public var kind: Kind {
            if let url = URL(string: text), URLNormalizer.isSavable(url), !text.contains(where: \.isWhitespace) {
                return .link
            }
            let codeHints = ["{", "}", ";", "=>", "$ ", "func ", "let ", "--", "&&"]
            return codeHints.contains { text.contains($0) } ? .code : .text
        }
    }

    public static let maximumTextLength = 10_000

    public private(set) var entries: [Entry] = []
    public let capacity: Int

    public init(capacity: Int = 30) {
        self.capacity = max(1, capacity)
    }

    /// Records `text` unless it is blank or too large. Copying the same text again
    /// moves it to the top instead of adding a duplicate.
    @discardableResult
    public mutating func record(_ text: String, at date: Date = .now) -> Bool {
        guard
            text.count <= Self.maximumTextLength,
            !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        else { return false }

        var pinned = false
        if let existing = entries.firstIndex(where: { $0.text == text }) {
            pinned = entries[existing].isPinned
            entries.remove(at: existing)
        }
        entries.insert(Entry(id: UUID(), text: text, copiedAt: date, isPinned: pinned), at: 0)
        trim()
        return true
    }

    public mutating func togglePin(_ id: UUID) {
        guard let i = entries.firstIndex(where: { $0.id == id }) else { return }
        entries[i].isPinned.toggle()
    }

    public mutating func remove(_ id: UUID) {
        entries.removeAll { $0.id == id }
    }

    public mutating func clear(keepingPinned: Bool = true) {
        entries.removeAll { !keepingPinned || !$0.isPinned }
    }

    private mutating func trim() {
        while entries.count > capacity, let last = entries.lastIndex(where: { !$0.isPinned }) {
            entries.remove(at: last)
        }
    }
}
